/* HaloChina: buildless, local-first learning library. No login or external scripts. */
(() => {
 'use strict';
 const C=window.HaloCore,V=window.HALO_VOCAB,L=window.HALO_LESSONS,G=window.HALO_GUIDES;
 const $=s=>document.querySelector(s),E=C.escape;
 const icons={book:'<path d="M4 4h6a3 3 0 0 1 3 3v14a4 4 0 0 0-4-2H4z"/><path d="M13 7a3 3 0 0 1 3-3h5v15h-4a4 4 0 0 0-4 2"/>',grid:'<rect x="3" y="3" width="7" height="7" rx="1"/><rect x="14" y="3" width="7" height="7" rx="1"/><rect x="3" y="14" width="7" height="7" rx="1"/><rect x="14" y="14" width="7" height="7" rx="1"/>',route:'<circle cx="6" cy="5" r="2"/><circle cx="18" cy="19" r="2"/><path d="M6 7v6a4 4 0 0 0 4 4h4a4 4 0 0 0 0-8h-2"/>',bookmark:'<path d="M6 3h12v18l-6-4-6 4z"/>',chart:'<path d="M4 20V10m8 10V4m8 16v-7M2 22h20"/>',grammar:'<path d="M4 5h16M8 3v3m-2 4h12M10 6c0 7-3 11-7 14m3-8c2 4 4 6 7 8m3-4h6m-7 4 4-10 4 10"/>',lesson:'<rect x="4" y="3" width="16" height="18" rx="2"/><path d="M8 7h8M8 11h8M8 15h4"/>',practice:'<path d="m14 4 6 6M4 20l4-1L21 6l-4-4L4 15zM3 22h18"/>',exam:'<rect x="5" y="4" width="14" height="18" rx="2"/><path d="M9 2h6v4H9zM9 11h6M9 15h6M9 19h3"/>',download:'<path d="M12 3v12m-5-5 5 5 5-5M4 16v5h16v-5"/>',sound:'<path d="m10 4-5 4H2v8h3l5 4zM14 8a6 6 0 0 1 0 8m3-11a10 10 0 0 1 0 14"/>',search:'<circle cx="10" cy="10" r="7"/><path d="m15 15 6 6"/>',arrow:'<path d="M4 12h16m-6-6 6 6-6 6"/>',check:'<path d="m5 12 4 4L19 6"/>',close:'<path d="m6 6 12 12M6 18 18 6"/>',cards:'<rect x="5" y="6" width="16" height="15" rx="2"/><path d="M3 17 1 4l15-2 1 3M10 12h7M10 16h5"/>'};
 icons.chat='<path d="M21 11a8 8 0 0 1-8 8H7l-5 3 2-6a8 8 0 1 1 17-5Z"/><path d="M7 10h10M7 14h6"/>';
 const icon=name=>`<svg viewBox="0 0 24 24" aria-hidden="true">${icons[name]||icons.book}</svg>`;
 const fresh=()=>({version:1,saved:[],known:[],completed:[],drafts:{},attempts:[],visits:[]});
 let storageOK=true,progress;try{const raw=localStorage.getItem('halochina-progress-v1');progress=raw?C.validProgress(JSON.parse(raw)):fresh();}catch{progress=fresh();storageOK=false;}
 function syncSaveStatus(){const badge=$('#save-status');if(badge){badge.innerHTML=storageOK?'<i></i> Đã lưu trên thiết bị':'<i></i> Chưa lưu được';badge.classList.toggle('unsaved',!storageOK);}}
 function persist(){try{localStorage.setItem('halochina-progress-v1',JSON.stringify(progress));storageOK=true;}catch{if(storageOK)toast('Bộ nhớ trình duyệt đã đầy; hãy xuất bản sao tiến độ.');storageOK=false;}syncSaveStatus();}
 const today=()=>{const d=new Date();return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`;};
 if(!progress.visits.includes(today())){progress.visits.push(today());persist();}
 const levelNames=['','Bắt đầu','Nền tảng','Sơ trung cấp','Trung cấp','Nâng cao','Chuyên sâu'];
 const levelGoals=['','Giới thiệu bản thân, hỏi đáp cơ bản và nói về sinh hoạt hằng ngày.','Kể trải nghiệm, so sánh và diễn đạt những nhu cầu thường gặp.','Liên kết câu, diễn tả kết quả và trình bày kế hoạch rõ ràng.','Nêu quan điểm, giải thích nguyên nhân và xử lý tình huống đa dạng.','Đọc lập luận, mô tả dữ liệu và diễn đạt ý kiến có căn cứ.','Phân tích sắc thái, tổng hợp thông tin và viết lập luận mạch lạc.'];
 const vocab=n=>V.filter(w=>w.level===n), lessons=n=>L.filter(l=>l.level===n);
 const durations=[0,40,60,83,85,110,125],examCounts=[0,40,60,70,70,72,82];
 let route={},listPage=1,query='',includePrevious=false,onlyUnknown=false,grammarQuery='',activeSession=null,flash=null,timerHandle=null,toastTimer=null;
 const resources=[['vocabulary','Từ vựng','Pinyin, âm Hán Việt, nghĩa tiếng Việt. Nghe phát âm và ôn bằng flashcard.','book','',n=>`${vocab(n).length.toLocaleString('vi-VN')} mục từ`],['grammar','Ngữ pháp','Cấu trúc, cách dùng, ví dụ có pinyin và những lỗi người Việt thường gặp.','grammar','peach',n=>`${lessons(n).length} điểm ngữ pháp`],['lessons','Giáo trình theo bài','Học từng chủ đề qua giải thích, ví dụ, luyện tập và tự viết câu.','lesson','blue',n=>`${lessons(n).length} bài học ngắn`],['topics','Chuyên đề học tập','Phát âm, chữ Hán, nghe, đọc, viết và phương pháp ghi nhớ hiệu quả.','grid','peach',()=>`${G.length} chuyên đề kỹ năng`],['practice','Bài tập','Luyện từ vựng, ngữ pháp, đọc và nghe. Chấm điểm kèm lời giải từng câu.','practice','',()=> 'Luyện theo kỹ năng'],['exam','Thi thử','Bài luyện tổng hợp có đồng hồ, bảng câu hỏi và báo cáo kết quả.','exam','pink',n=>`${examCounts[n]} câu · ${durations[n]} phút`],['downloads','Tài liệu tải xuống','Xuất danh sách từ, bảng ngữ pháp, phiếu luyện viết và bảng tự kiểm tra.','download','blue',()=> 'CSV · In / lưu PDF']];
 function toast(message){$('#toast').textContent=message;$('#toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),3200);}
 const href=(view,level=route.level)=>`#/${view}/${level}`;
 const button=(label,action,extra='',classes='')=>`<button class="button ${classes}" data-action="${action}" ${extra}>${label}</button>`;
 function pageTitle(title,subtitle,n=route.level){return `<div class="page-title"><a class="back-link" href="${href('library',n)}">← Thư viện HSK${n}</a><h1>${title}</h1><p>${subtitle}</p></div>`;}
 function tabs(active,n=route.level){return `<nav class="tabs" aria-label="Loại tài liệu HSK${n}">${resources.map(([id,title])=>`<a class="tab ${active===id?'active':''}" href="${href(id,n)}">${title}</a>`).join('')}</nav>`;}
 function renderNav(){
  const lv=route.level||1;
  $('#main-nav').innerHTML=[['library','Thư viện tài liệu','book'],['communication','Giao tiếp hằng ngày','chat'],['roadmap','Lộ trình học','route'],['games','Trò chơi','cards'],['saved','Từ đã lưu','bookmark'],['progress','Tiến độ của tôi','chart']].map(([view,title,i])=>{
   const active=route.view===view||view==='library'&&(resources.some(r=>r[0]===route.view)||route.view==='lesson')||view==='games'&&['game','game-result','game-guide'].includes(route.view)||view==='communication'&&route.view==='daily-topic';
   return `<a class="nav-item ${active?'active':''}" href="${href(view,lv)}">${icon(i)}${title}${view==='saved'?`<span class="nav-count">${progress.saved.length}</span>`:view==='games'?'<span class="nav-count game-nav-count">120</span>':''}</a>`;
  }).join('');
  $('#level-nav').innerHTML=[1,2,3,4,5,6].map(n=>`<a class="level-link ${n===lv?'active':''}" href="${href('library',n)}"><span class="level-dot">${n}</span><span>HSK ${n}</span><span class="level-description">${levelNames[n]}</span></a>`).join('');
  $('#breadcrumb').textContent=route.view==='library'?'Thư viện tài liệu':['communication','daily-topic'].includes(route.view)?'Giao tiếp hằng ngày':({games:'Trò chơi · Hành trình Thỏ Mây',game:'Trò chơi · Đang luyện tập','game-result':'Trò chơi · Kết quả','game-guide':'Cách chơi',saved:'Từ đã lưu',progress:'Tiến độ học tập',sources:'Về HaloChina',roadmap:'Lộ trình học',lesson:'Bài học'}[route.view]||resources.find(r=>r[0]===route.view)?.[1]||'Thư viện')+` / HSK${lv}`;
 }
 function renderLibrary(){const n=route.level;return `<section class="hero"><div class="hero-copy"><div class="eyebrow">CHÀO BẠN, CÙNG HỌC MỘT CHÚT NHÉ</div><h1>Mỗi ngày một chút,<br><em>tiếng Trung tiến xa.</em></h1><p>Từ những nét chữ đầu tiên đến những cuộc trò chuyện tự tin.<br>Thư viện HSK1–HSK6, sẵn sàng cho hành trình của bạn.</p><div class="hero-bottom"><a class="button light" href="${href('lessons',n)}">Bắt đầu học ${icon('arrow')}</a><span class="hero-small"><b>5.400</b> mục từ · <b>108</b> bài học</span></div></div><div class="hero-art" aria-hidden="true"><div class="orbit"></div><span class="stamp">好<br>好</span><span class="hero-hanzi">学</span><span class="art-note">学 而 不 厌</span><span class="sparkle">✳</span></div></section><section aria-labelledby="choose-level"><div class="section-heading"><div><h2 id="choose-level">Bạn đang ở đâu trên hành trình?</h2><p>Chọn cấp độ để tìm tài liệu phù hợp với bạn.</p></div><a class="text-link" href="${href('roadmap',n)}">Xem lộ trình ↗</a></div><div class="levels">${[1,2,3,4,5,6].map(lv=>{const count=progress.known.filter(id=>vocab(lv).some(w=>w.id===id)).length;return `<a class="level-card ${lv===n?'selected':''}" href="${href('library',lv)}" ${lv===n?'aria-current="page"':''}><span class="lv-name">HSK ${lv}</span><span class="lv-range">${levelNames[lv]}</span><span class="lv-count">${vocab(lv).length.toLocaleString('vi-VN')} mục từ</span>${lv===n?'<span class="level-tick">✓</span>':''}<div class="mini-bar"><span style="width:${count/vocab(lv).length*100}%"></span></div></a>`;}).join('')}</div></section><section aria-labelledby="library-title"><div class="library-head"><div class="level-title"><div class="level-badge">${n}</div><div><h2 id="library-title">Bộ tài liệu HSK${n}</h2><p>Mọi thứ bạn cần, sắp xếp để dễ bắt đầu.</p></div></div><span class="edition-tag">TỪ VỰNG · ĐỀ CƯƠNG 2025-11</span></div><div class="resource-grid">${resources.map(([view,title,desc,i,tone,count],index)=>`<a class="resource-card" href="${href(view,n)}"><div class="resource-top"><span class="resource-icon ${tone}">${icon(i)}</span><span class="resource-number">0${index+1}</span></div><h3>${title} HSK${n}</h3><p>${desc}</p><div class="resource-footer"><span>${count(n)}</span><span class="card-arrow">↗</span></div></a>`).join('')}</div></section><div class="callout"><span class="callout-symbol">✧</span><p><strong>Học để hiểu, ôn để nhớ.</strong> Bài học do HaloChina biên soạn; từ điển có ghi nguồn.<br>Tiến độ được lưu trên trình duyệt này. Bài thi thử là bài luyện, không phải đề thi chính thức.</p><a href="#/sources">Tìm hiểu thêm ↗</a></div>`;}
 function currentWords(saved=false){let a=saved?V.filter(w=>progress.saved.includes(w.id)):V.filter(w=>includePrevious?w.level<=route.level:w.level===route.level);if(onlyUnknown)a=a.filter(w=>!progress.known.includes(w.id));if(query.trim())a=a.filter(w=>C.match(w,query));return a;}
 function renderVocabulary(saved=false){const n=route.level;return pageTitle(saved?'Góc từ vựng của bạn':`Từ vựng HSK${n}`,saved?'Những từ bạn muốn quay lại. Lưu từ trong thư viện rồi ôn từng chút một.':`${vocab(n).length.toLocaleString('vi-VN')} mục từ mới trong đề cương 2025-11. Pinyin · âm Hán Việt theo chữ · nghĩa tiếng Việt.`)+(saved?'':tabs('vocabulary'))+`<div class="toolbar"><label class="search-wrap">${icon('search')}<input class="search" id="vocab-search" type="search" placeholder="Tìm chữ Hán, pinyin hoặc nghĩa tiếng Việt…" value="${E(query)}" aria-label="Tìm từ vựng"></label>${button(icon('cards')+' Flashcard','flash-open','', 'ghost')}${button(icon('download')+' Xuất CSV','export-vocab','','ghost')}${button('In / lưu PDF','print-vocab','','ghost')}</div><div class="toolbar">${!saved?`<label class="checkbox-label"><input id="include-previous" type="checkbox" ${includePrevious?'checked':''}> Gồm cả các cấp trước</label>`:''}<label class="checkbox-label"><input id="only-unknown" type="checkbox" ${onlyUnknown?'checked':''}> Chỉ từ chưa nhớ</label><span class="subtle">Âm Hán Việt được ghép theo chữ; dấu / chỉ các âm có thể có.</span></div><div id="vocab-results">${vocabResults(saved)}</div>`;}
 function renderPagination(total,position){
  const pages=Math.max(1,Math.ceil(total/30));
  const range=`${(listPage-1)*30+1}–${Math.min(listPage*30,total)} / ${total.toLocaleString('vi-VN')} mục từ`;
  return `<nav class="pagination pagination-visible pager-${position}" aria-label="Phân trang ${position==='top'?'đầu':'cuối'} danh sách"><span class="pager-range">${range}</span><div class="pagination-buttons"><button class="button ghost pager-prev" data-action="vocab-prev" ${listPage===1?'disabled':''} aria-label="Trang trước">← <span>Trước</span></button><label class="pager-current">Trang <select data-vocab-page aria-label="Chọn trang ${position==='top'?'đầu':'cuối'} danh sách">${Array.from({length:pages},(_,i)=>`<option value="${i+1}" ${i+1===listPage?'selected':''}>${i+1} / ${pages}</option>`).join('')}</select></label><button class="button pager-next" data-action="vocab-next" ${listPage===pages?'disabled':''} aria-label="Trang sau"><span>Sau</span> →</button></div></nav>`;
 }
 function vocabResults(saved=false){
  const a=currentWords(saved),pages=Math.max(1,Math.ceil(a.length/30));listPage=Math.max(1,Math.min(listPage,pages));const chunk=a.slice((listPage-1)*30,listPage*30);
  if(!chunk.length)return `<div class="empty"><h2>${saved&&!query?'Chưa có từ nào được lưu':'Chưa tìm thấy từ phù hợp'}</h2><p>${saved&&!query?'Bấm biểu tượng đánh dấu bên cạnh một từ trong thư viện để lưu vào góc học tập của bạn.':'Thử tìm bằng chữ Hán, pinyin không dấu hoặc một nghĩa ngắn hơn.'}</p><a class="button ghost" href="${href('vocabulary')}">Mở thư viện từ vựng</a></div>`;
  return `<div class="filter-result">${a.length.toLocaleString('vi-VN')} mục từ${query?' phù hợp':''} · ${a.filter(w=>progress.known.includes(w.id)).length} từ đã nhớ trong kết quả</div>${renderPagination(a.length,'top')}<div class="table-shell" tabindex="-1" aria-label="Từ vựng trang ${listPage}"><table><thead><tr><th>CHỮ HÁN</th><th>PINYIN / HÁN VIỆT</th><th>NGHĨA TIẾNG VIỆT</th><th>ÔN TẬP</th></tr></thead><tbody>${chunk.map(w=>`<tr><td class="hanzi" lang="zh">${E(w.hanzi)}<div class="subtle">HSK${w.level}</div></td><td><div class="pinyin">${E(w.pinyin)}</div><div class="hanviet">${E(w.hanviet)}</div></td><td class="meaning">${E(w.vi||w.en)}${!w.vi?'<small> · nghĩa tiếng Anh</small>':''}</td><td class="actions-cell"><button class="icon-button" data-action="speak-word" data-id="${w.id}" aria-label="Nghe ${E(w.hanzi)}">${icon('sound')}</button><button class="icon-button ${progress.saved.includes(w.id)?'saved':''}" data-action="save-word" data-id="${w.id}" aria-label="${progress.saved.includes(w.id)?'Bỏ lưu':'Lưu'} ${E(w.hanzi)}" aria-pressed="${progress.saved.includes(w.id)}">${icon('bookmark')}</button><button class="icon-button ${progress.known.includes(w.id)?'saved':''}" data-action="know-word" data-id="${w.id}" aria-label="${progress.known.includes(w.id)?'Đánh dấu chưa nhớ':'Đánh dấu đã nhớ'} ${E(w.hanzi)}" aria-pressed="${progress.known.includes(w.id)}">${icon('check')}</button></td></tr>`).join('')}</tbody></table></div>${renderPagination(a.length,'bottom')}`;
 }
 function changeVocabPage(page){
  const count=currentWords(route.view==='saved').length,pages=Math.max(1,Math.ceil(count/30)),next=Math.max(1,Math.min(pages,Number(page)||1));if(next===listPage)return;
  listPage=next;$('#vocab-results').innerHTML=vocabResults(route.view==='saved');const table=$('#vocab-results .table-shell'),reduced=matchMedia('(prefers-reduced-motion: reduce)').matches;
  table?.focus({preventScroll:true});$('#vocab-results .pager-top')?.scrollIntoView({block:'start',behavior:reduced?'instant':'smooth'});
  if(table?.animate&&!reduced)table.animate([{opacity:.5,transform:'translateY(6px)'},{opacity:1,transform:'translateY(0)'}],{duration:240,easing:'ease-out'});
  toast(`Đã chuyển sang trang ${listPage} / ${pages}.`);
 }
 function example(l){return `<div class="example"><div class="example-top"><div class="zh" lang="zh">${E(l.zh)}</div><button class="icon-button" data-action="speak-lesson" data-id="${l.id}" aria-label="Nghe câu ví dụ">${icon('sound')}</button></div><p class="pinyin">${E(l.pinyin)}</p><p class="vi">${E(l.vi)}</p></div>`;}
 function renderGrammar(){return pageTitle(`Ngữ pháp HSK${route.level}`,`${lessons(route.level).length} cấu trúc cốt lõi do HaloChina biên soạn. Mở từng mục để xem cách dùng, ví dụ và lỗi cần tránh.`)+tabs('grammar')+`<div class="toolbar"><label class="search-wrap">${icon('search')}<input class="search" id="grammar-search" type="search" value="${E(grammarQuery)}" placeholder="Tìm cấu trúc hoặc cách dùng…" aria-label="Tìm ngữ pháp"></label>${button('In / lưu PDF','print-grammar','','ghost')}</div><div id="grammar-results">${grammarResults()}</div>`;}
 function grammarResults(){const a=lessons(route.level).filter(l=>C.normalize(`${l.grammar} ${l.pattern} ${l.explanation}`).includes(C.normalize(grammarQuery)));return a.length?`<div class="grammar-list">${a.map(l=>`<details class="grammar-item"><summary><span><span class="grammar-label">${String(l.number).padStart(2,'0')}</span>${E(l.grammar)}</span></summary><div class="grammar-body"><div class="formula">${E(l.pattern)}</div><p>${E(l.explanation)}</p>${example(l)}<div class="tip"><strong>Lưu ý:</strong> ${E(l.tip)}</div><a class="button ghost small" href="#/lesson/${l.level}/${l.id}">Học và luyện cấu trúc này ↗</a></div></details>`).join('')}</div>`:'<div class="empty">Không tìm thấy cấu trúc phù hợp.</div>';}
 function renderLessons(){return pageTitle(`Giáo trình HSK${route.level} theo bài`,`${levelGoals[route.level]} Mỗi bài học ngắn gồm một điểm ngữ pháp, ví dụ, luyện hiểu và phần tự viết.`)+tabs('lessons')+`<div class="lesson-grid">${lessons(route.level).map(l=>`<a class="lesson-card" href="#/lesson/${l.level}/${l.id}"><span class="lesson-num">BÀI ${String(l.number).padStart(2,'0')}</span>${progress.completed.includes(l.id)?'<span class="completion">✓ Đã học</span>':''}<h3>${E(l.title)}</h3><p>${E(l.grammar)}</p><div class="lesson-meta"><span>8–12 phút</span><span>·</span><span>Ví dụ & luyện tập</span></div></a>`).join('')}</div>`;}
 function renderLesson(){const l=L.find(x=>x.id===route.id&&x.level===route.level);if(!l)return renderNotFound();const next=lessons(l.level).find(x=>x.number===l.number+1);return pageTitle(`Bài ${l.number}. ${E(l.title)}`,`HSK${l.level} · ${E(l.grammar)} · Bài học do HaloChina biên soạn`)+`<div class="reading-layout"><article class="panel"><span class="level-pill">MỤC TIÊU BÀI HỌC</span><h2>${E(l.grammar)}</h2><p>Hiểu và dùng được cấu trúc sau trong tình huống “${E(l.title.toLowerCase())}”. Sau bài học, hãy tự viết hai câu mới và đọc thành tiếng.</p><div class="formula">${E(l.pattern)}</div><h3>1. Hiểu cách dùng</h3><p>${E(l.explanation)}</p><h3>2. Nghe và đọc ví dụ</h3>${example(l)}<p>Đọc chậm theo từng cụm, xác định chủ ngữ và vị ngữ. Thay một thông tin trong câu (người, thời gian hoặc địa điểm) rồi đọc lại để kiểm tra bạn hiểu cấu trúc.</p><div class="tip"><strong>Lỗi cần tránh:</strong> ${E(l.tip)}</div><h3>3. Kiểm tra nhanh</h3><div id="inline-exercise" data-lesson="${l.id}"><p class="question-text">${E(l.cloze)}</p><div class="choices">${C.shuffle([l.answer,...l.wrong]).map((answer,i)=>`<button class="choice" data-action="inline-answer" data-id="${l.id}" data-answer="${E(answer)}"><span class="letter">${'ABCD'[i]}</span>${E(answer)}</button>`).join('')}</div><div id="inline-feedback" role="status"></div></div><h3>4. Tự viết để ghi nhớ</h3><p>Viết hai câu mới với “${E(l.pattern)}”. Gợi ý: một câu nói về bản thân và một câu nói về người bạn biết. Tự kiểm tra vị trí các thành phần và lưu ý ở trên.</p><div class="writing-box"><label for="lesson-draft">Bản nháp của bạn · tự lưu trên thiết bị</label><textarea id="lesson-draft" data-id="${l.id}" placeholder="Viết câu tiếng Trung của bạn ở đây…">${E(progress.drafts[l.id]||'')}</textarea><p class="privacy-note">Phần tự viết để luyện diễn đạt, không chấm điểm tự động.</p></div><div class="actions-inline">${button(progress.completed.includes(l.id)?'✓ Đã hoàn thành':'Đánh dấu hoàn thành','complete-lesson',`data-id="${l.id}"`)}${next?`<a class="button ghost" href="#/lesson/${next.level}/${next.id}">Bài tiếp theo →</a>`:`<a class="button ghost" href="${href('practice')}">Ôn tập toàn cấp →</a>`}</div></article><aside class="reading-side"><div class="panel"><h3>Học theo 4 bước</h3><ul class="checklist"><li>Hiểu cấu trúc và cách dùng</li><li>Nghe và đọc ví dụ</li><li>Làm câu kiểm tra nhanh</li><li>Tự viết và xem lại lỗi</li></ul><a class="button ghost" href="${href('vocabulary')}">Tra từ vựng ${icon('book')}</a><a class="button ghost" href="${href('lessons')}">Danh sách bài học</a>${button('In bài học','print-page','','ghost')}</div></aside></div>`;}
 function renderTopics(){return pageTitle(`Chuyên đề học tập HSK${route.level}`,'Những kỹ năng đi cùng bạn từ nền tảng đến nâng cao. Đọc hướng dẫn rồi áp dụng ngay vào bài học của cấp đang chọn.')+tabs('topics')+`<div class="lesson-grid">${G.map((g,i)=>`<a class="lesson-card" href="#/guide/${route.level}/${g.id}"><span class="lesson-num">CHUYÊN ĐỀ 0${i+1}</span><h3>${E(g.title)}</h3><p>${E(g.intro)}</p><div class="lesson-meta"><span>${g.sections.length} phần hướng dẫn</span><span>↗</span></div></a>`).join('')}</div>`;}
 function renderGuide(){const g=G.find(x=>x.id===route.id);if(!g)return renderNotFound();return pageTitle(g.title,`Chuyên đề kỹ năng · Áp dụng cho HSK${route.level}`)+`<article class="panel guide-body"><div class="guide-goal"><strong>Mục tiêu cấp HSK${route.level}:</strong> ${levelGoals[route.level]}</div>${g.sections.map(([title,text])=>`<h2>${E(title)}</h2><p>${E(text)}</p>`).join('')}<h2>Áp dụng ngay</h2><p>Chọn một bài HSK${route.level}, đọc câu ví dụ, nghe lại khi che văn bản và tự đặt một câu theo cùng cấu trúc. Quay lại chuyên đề để xem bạn đã bỏ qua bước nào.</p><div class="actions-inline"><a class="button" href="${href('lessons')}">Chọn bài học →</a>${button('In chuyên đề','print-page','','ghost')}</div></article>`;}
 function renderRoadmap(){return pageTitle('Một lộ trình, theo nhịp của bạn','Bắt đầu từ cấp bạn thấy thoải mái. Mỗi ngày ôn từ, học một cấu trúc và làm một bài luyện ngắn.')+`<div class="lesson-grid">${[1,2,3,4,5,6].map(n=>{const done=progress.completed.filter(id=>lessons(n).some(l=>l.id===id)).length;return `<a class="lesson-card" href="${href('lessons',n)}"><span class="lesson-num">CHẶNG 0${n} · HSK${n}</span><h3>${levelNames[n]}</h3><p>${levelGoals[n]}</p><div class="progress-track"><i style="width:${done/lessons(n).length*100}%"></i></div><p>${done}/${lessons(n).length} bài đã học · ${vocab(n).length} mục từ mới</p><div class="lesson-meta"><span>Tiếp tục hành trình</span><span>→</span></div></a>`;}).join('')}</div><div class="callout"><span class="callout-symbol">✳</span><p><strong>Nhịp học gợi ý: 30 phút.</strong> 8 phút ôn từ cũ · 10 phút học bài · 7 phút luyện tập · 5 phút tự viết.<br>Đây là lộ trình tự học, không cam kết thời gian đạt chứng chỉ.</p><a href="#/guide/${route.level}/planning">Cách ôn tập ↗</a></div>`;}
 function renderDownloads(){return pageTitle(`Tài liệu HSK${route.level} mang theo bạn`,'Tạo tài liệu từ nội dung có sẵn. CSV mở bằng Excel hoặc nhập vào Google Sheets; chức năng in cho phép chọn “Lưu dưới dạng PDF” trong trình duyệt.')+tabs('downloads')+`<div class="download-grid">${[
 ['book',`Danh sách ${vocab(route.level).length} mục từ`,'Chữ Hán, pinyin, âm Hán Việt, nghĩa và cấp độ. Có bản CSV để tra cứu và bản in để ôn tập.',button('↓ Tải CSV','export-all-vocab')+button('In / lưu PDF','print-all-vocab','','ghost')],
 ['grammar','Sổ tay ngữ pháp',`${lessons(route.level).length} cấu trúc, giải thích, ví dụ có pinyin, bản dịch và lỗi thường gặp.`,button('In / lưu PDF','print-grammar')],
 ['practice','Phiếu luyện viết chữ Hán','Các từ được chia trang, mỗi chữ có ô vuông để tự viết. Có thể chọn xuất toàn cấp hoặc chỉ những từ đã lưu.',button('Tạo phiếu luyện viết','print-handwriting')],
 ['exam','Bảng tự kiểm tra từ vựng','Bản CSV gồm chữ Hán, cột tự điền nghĩa và cột đáp án. Ẩn cột đáp án trong Excel / Google Sheets trước khi ôn.',button('↓ Tải bảng tự kiểm tra','export-selftest')],
 ['lesson','Bài tập điền từ và lời giải',`${lessons(route.level).length} câu điền cấu trúc đã học, có phần đáp án và giải thích ở cuối để tự kiểm tra.`,button('In / lưu PDF','print-exercises')],
 ['chart','Bản sao tiến độ học tập','Lưu từ đã đánh dấu, bài hoàn thành, bản nháp và lịch sử làm bài. Nhập lại trên trình duyệt khác để tiếp tục học.',button('↓ Xuất tiến độ JSON','export-progress')+button('Nhập tiến độ','import-progress','','ghost')]
 ].map(([i,title,desc,actions])=>`<div class="download-card"><span class="resource-icon">${icon(i)}</span><h3>${title}</h3><p>${desc}</p>${actions}</div>`).join('')}</div><div class="notice" style="margin-top:20px">CSV và tài liệu in kèm thông tin ghi nguồn. Nội dung từ điển phái sinh được chia sẻ theo CC BY-SA 4.0. Các phiếu được tạo trực tiếp, không yêu cầu tài khoản Google.</div>`;}
 function loadSession(){try{const s=JSON.parse(localStorage.getItem('halochina-session-v1')||'null');if(!s||!Array.isArray(s.questions)||!s.questions.length||s.questions.length>100||!['practice','exam'].includes(s.mode)||!Number.isInteger(s.level)||!s.startedAt||typeof s.answers!=='object'||s.questions.some(q=>!q||!Array.isArray(q.options)||q.options.length!==4||!q.options.includes(q.answer)))return null;return s;}catch{return null;}}
 function saveSession(){try{if(activeSession)localStorage.setItem('halochina-session-v1',JSON.stringify(activeSession));else localStorage.removeItem('halochina-session-v1');}catch{toast('Không lưu được bài đang làm. Hãy hoàn thành trước khi đóng trang.');}}
 function renderSetup(mode){const n=route.level,s=loadSession();return pageTitle(mode==='exam'?`Thi thử HSK${n}`:`Luyện tập HSK${n}`,mode==='exam'?'Bài luyện tổng hợp do HaloChina tạo từ nội dung đã học. Có đồng hồ, chuyển câu và chấm điểm khi nộp bài.':'Luyện theo kỹ năng, biết kết quả ngay sau mỗi câu và đọc giải thích để hiểu vì sao.')+tabs(mode==='exam'?'exam':'practice')+`<div class="quiz-setup">${s?`<div class="notice">Bạn có một bài ${s.mode==='exam'?'thi thử':'luyện tập'} HSK${s.level} đang làm (${Object.keys(s.answers).length}/${s.questions.length} câu). <div class="actions-inline" style="margin-top:10px">${button('Làm tiếp bài đang dở','resume-quiz','','small')}${button('Bỏ bài đang dở','discard-quiz','','ghost small')}</div></div>`:''}<div class="panel"><span class="level-pill">${mode==='exam'?'THỬ SỨC CỦA BẠN':'HỌC QUA TỪNG CÂU HỎI'}</span><h2>${mode==='exam'?'Một lần luyện tập, một bước tiến mới.':'Bạn muốn luyện gì hôm nay?'}</h2><p>${mode==='exam'?`Bài gồm ${examCounts[n]} câu với thời gian ${durations[n]} phút. Ngữ pháp và đọc dùng các bài học của HaloChina; phần nghe dùng giọng tổng hợp của thiết bị.`:'Chọn nội dung phù hợp rồi bắt đầu. Phần nghe cần thiết bị có giọng đọc tiếng Trung; bạn có thể luyện kỹ năng khác nếu thiết bị chưa hỗ trợ.'}</p><div class="notice">Nội dung tự biên soạn để ôn tập. Cấu trúc và thang điểm ở đây không mô phỏng đầy đủ kỳ thi HSK chính thức.</div>${mode==='practice'?`<div class="setup-row"><div class="setup-field"><label for="practice-kind">Nội dung luyện</label><select id="practice-kind"><option value="mixed">Tổng hợp các kỹ năng</option><option value="vocab">Nghĩa từ vựng</option><option value="pinyin">Nhận diện pinyin</option><option value="grammar">Điền từ ngữ pháp</option><option value="reading">Đọc hiểu câu</option><option value="listening">Nghe hiểu câu</option><option value="saved">Từ đã lưu ở cấp này</option></select></div><div class="setup-field"><label for="practice-count">Số câu mong muốn</label><select id="practice-count"><option>10</option><option selected>20</option><option>30</option><option>50</option></select></div></div><label class="checkbox-label"><input type="checkbox" id="practice-cumulative"> Ôn cả từ vựng các cấp trước</label><p class="privacy-note">Với kỹ năng có ít câu, bài luyện dùng số câu thực tế có sẵn.</p>`:`<div class="progress-cards" style="grid-template-columns:repeat(3,1fr)"><div class="stat-card"><strong>${examCounts[n]}</strong><span>Câu hỏi</span></div><div class="stat-card"><strong>${durations[n]}</strong><span>Phút làm bài</span></div><div class="stat-card"><strong>100</strong><span>Điểm luyện tập</span></div></div>`}<div class="actions-inline" style="margin-top:24px">${button(`Bắt đầu ${mode==='exam'?'thi thử':'luyện tập'} ${icon('arrow')}`,'start-quiz',`data-mode="${mode}"`)}${button(icon('sound')+' Thử âm thanh','test-sound','','ghost')}</div><p class="privacy-note">Bài làm được lưu trên trình duyệt này. Đóng trang không dừng đồng hồ thi thử.</p></div></div>`;}
 function startQuiz(mode){const existing=loadSession();if(existing){toast('Hãy làm tiếp hoặc bỏ bài đang dở trước khi bắt đầu bài mới.');return;}
 const n=route.level,kind=$('#practice-kind')?.value||'mixed';let words=V;if(kind==='saved')words=V.filter(w=>progress.saved.includes(w.id));const kinds=kind==='mixed'?['vocab','grammar','reading','listening']:kind==='saved'?['vocab']:[kind];
 const q=C.questions({level:n,count:mode==='exam'?examCounts[n]:Number($('#practice-count')?.value||20),vocabulary:words,lessons:L,kinds,cumulative:!!$('#practice-cumulative')?.checked});if(!q.length){toast('Chưa có từ đã lưu ở phạm vi này. Hãy lưu vài từ trước.');return;}
 activeSession={mode,level:n,questions:q,answers:{},index:0,startedAt:Date.now(),duration:mode==='exam'?durations[n]*60:0};saveSession();location.hash=`#/quiz/${n}`;
 }
 function renderQuiz(){if(!activeSession)activeSession=loadSession();const s=activeSession;if(!s)return renderSetup('practice');const q=s.questions[s.index],chosen=s.answers[q.id],show=s.mode==='practice'&&chosen!==undefined,stats=C.score(s);return pageTitle(`${s.mode==='exam'?'Thi thử':'Luyện tập'} HSK${s.level}`,s.mode==='exam'?'Chọn đáp án và kiểm tra lại các câu trước khi nộp bài.':'Chọn một đáp án, đọc giải thích rồi chuyển sang câu tiếp theo.')+`<div class="quiz-layout"><div class="panel"><div class="quiz-header"><span>Câu ${s.index+1} / ${s.questions.length}</span>${s.mode==='exam'?'<span class="timer" id="quiz-timer" aria-label="Thời gian còn lại"></span>':`<span>${stats.answered} câu đã trả lời</span>`}</div><div class="progress-track"><i style="width:${stats.answered/stats.total*100}%"></i></div><div class="question-type">${E(q.label)}</div><div class="question-text">${E(q.prompt)}</div>${q.pinyin?`<div class="pinyin">${E(q.pinyin)}</div>`:''}${q.passage?`<div class="question-passage" lang="zh">${E(q.passage)}</div>`:''}${q.speak?`<div class="actions-inline">${button(icon('sound')+' Nghe câu hỏi','speak-question','','ghost')}<span class="subtle">Giọng tổng hợp · có thể nghe lại</span></div>`:''}<div class="choices">${q.options.map((a,i)=>`<button class="choice ${chosen===a?'chosen':''} ${show&&a===q.answer?'correct':''} ${show&&chosen===a&&a!==q.answer?'incorrect':''}" data-action="quiz-answer" data-answer="${E(a)}" ${show?'disabled':''}><span class="letter">${'ABCD'[i]}</span>${E(a)}</button>`).join('')}</div>${show?`<div class="feedback ${chosen!==q.answer?'wrong':''}" role="status"><strong>${chosen===q.answer?'✓ Chính xác.':'Cùng xem lại nhé.'}</strong> ${E(q.explanation)}</div>`:''}<div class="quiz-actions">${button('← Câu trước','quiz-prev',s.index===0?'disabled':'','ghost')}${s.index===s.questions.length-1?button('Nộp bài','submit-quiz'):button('Câu tiếp →','quiz-next')}</div></div><aside class="quiz-sidebar"><div class="panel"><h3>Bảng câu hỏi</h3><div class="question-map">${s.questions.map((x,i)=>`<button class="map-button ${s.answers[x.id]!==undefined?'answered':''} ${i===s.index?'current':''}" data-action="quiz-goto" data-index="${i}" aria-label="Đến câu ${i+1}">${i+1}</button>`).join('')}</div><p class="subtle">Ô xanh là câu đã trả lời. Câu bỏ trống được tính chưa đúng.</p>${button('Nộp bài','submit-quiz','','small')}<a class="button ghost small" style="margin-top:9px" href="${href('library',s.level)}">Tạm rời bài</a></div></aside></div>`;}
 function tickTimer(){if(timerHandle)clearInterval(timerHandle);timerHandle=null;if(route.view!=='quiz'||!activeSession||activeSession.mode!=='exam')return;const tick=()=>{const s=activeSession;if(!s)return;const left=Math.max(0,Math.ceil(s.duration-(Date.now()-s.startedAt)/1000));const target=$('#quiz-timer');if(target)target.textContent=`${String(Math.floor(left/60)).padStart(2,'0')}:${String(left%60).padStart(2,'0')}`;if(left<=0)finishQuiz(true);};tick();if(route.view==='quiz')timerHandle=setInterval(tick,1000);}
 function requestSubmit(){const s=activeSession,unanswered=s.questions.length-Object.keys(s.answers).length;openDialog('Nộp bài luyện tập',`<p class="subtle">${unanswered?`Bạn còn ${unanswered} câu chưa trả lời; những câu này sẽ được tính chưa đúng.`:'Bạn đã trả lời tất cả câu hỏi.'} Sau khi nộp, bạn sẽ xem được điểm và giải thích.</p><div class="actions-inline">${button('Xác nhận nộp bài','confirm-submit')}${button('Quay lại làm bài','close-dialog','','ghost')}</div>`);}
 function finishQuiz(timeout=false){const s=activeSession;if(!s)return;clearInterval(timerHandle);timerHandle=null;const result=C.score(s);const seconds=Math.max(0,Math.floor((Date.now()-s.startedAt)/1000));const full={...s,finishedAt:Date.now(),timeout,seconds};progress.attempts.push({level:s.level,correct:result.correct,total:result.total,at:Date.now(),mode:s.mode,seconds});progress.attempts=progress.attempts.slice(-100);persist();try{localStorage.setItem('halochina-result-v1',JSON.stringify(full));}catch{}window.lastResult=full;activeSession=null;saveSession();$('#reader-dialog').close();location.hash=`#/results/${s.level}`;}
 function getResult(){if(window.lastResult)return window.lastResult;try{const s=JSON.parse(localStorage.getItem('halochina-result-v1')||'null');return s?.questions?.length&&s.answers?s:null;}catch{return null;}}
 function renderResults(){const s=getResult();if(!s)return `<div class="empty"><h2>Chưa có bài làm để xem</h2><p>Hoàn thành một bài luyện để nhận kết quả và giải thích.</p><a class="button" href="${href('practice')}">Bắt đầu luyện tập</a></div>`;const score=C.score(s);return pageTitle(`Kết quả ${s.mode==='exam'?'thi thử':'luyện tập'} HSK${s.level}`,'Điểm số giúp bạn biết cần ôn gì tiếp theo. Hãy dành thời gian đọc lại các câu chưa đúng.')+`<section class="panel result-hero"><span class="level-pill">MỘT BƯỚC TIẾN MỚI</span><div class="result-score">${score.percent}<span style="font-size:22px;letter-spacing:0"> / 100</span></div><h2>${score.percent>=80?'Bạn đang tiến bộ rất tốt!':score.percent>=50?'Bạn đã có nền tảng, cùng luyện thêm nhé.':'Mỗi lỗi sai là một điều mới để học.'}</h2><p>${s.timeout?'Bài đã tự nộp khi hết thời gian. ':''}Điểm luyện tập của HaloChina, không quy đổi thành điểm chứng chỉ HSK.</p><div class="result-meta"><span><strong>${score.correct}/${score.total}</strong>Câu đúng</span><span><strong>${score.total-score.answered}</strong>Chưa trả lời</span><span><strong>${Math.floor(s.seconds/60)}:${String(s.seconds%60).padStart(2,'0')}</strong>Thời gian</span></div><div class="actions-inline" style="justify-content:center">${button('Ôn lại câu sai','retry-wrong')}<a class="button ghost" href="${href('practice',s.level)}">Bài luyện mới</a>${button('↓ Kết quả CSV','export-result','','ghost')}</div></section><div class="panel"><h2>Đáp án & giải thích</h2>${s.questions.map((q,i)=>`<article class="review-item"><span class="review-status ${s.answers[q.id]!==q.answer?'wrong':''}">${s.answers[q.id]===q.answer?'✓ ĐÚNG':s.answers[q.id]===undefined?'○ CHƯA TRẢ LỜI':'↻ CẦN ÔN LẠI'} · CÂU ${i+1}</span><div class="question-text">${E(q.prompt)}</div>${q.passage?`<p lang="zh">${E(q.passage)}</p>`:''}<p>Bạn chọn: <strong>${E(s.answers[q.id]??'Chưa chọn')}</strong> · Đáp án: <strong>${E(q.answer)}</strong></p><p>${E(q.explanation)}</p>${q.lessonId?`<a class="text-link" href="#/lesson/${s.level}/${q.lessonId}">Xem lại bài học ↗</a>`:''}</article>`).join('')}</div>`;}
 function renderProgress(){const all=progress.attempts,correct=all.reduce((s,a)=>s+a.correct,0),total=all.reduce((s,a)=>s+a.total,0);return pageTitle('Bạn đã đi được một đoạn đường','Những bước nhỏ đều đáng được ghi nhận. Dữ liệu này chỉ lưu trong trình duyệt hiện tại; hãy xuất bản sao để mang sang thiết bị khác.')+`<div class="progress-cards"><div class="stat-card"><strong>${progress.known.length}</strong><span>Từ đã nhớ</span></div><div class="stat-card"><strong>${progress.completed.length}</strong><span>Bài đã hoàn thành / 108</span></div><div class="stat-card"><strong>${all.length}</strong><span>Lượt luyện tập</span></div><div class="stat-card"><strong>${total?Math.round(correct/total*100):0}%</strong><span>Tỷ lệ đúng trung bình</span></div></div><div class="panel"><h2>Tiến độ từng cấp</h2>${[1,2,3,4,5,6].map(n=>{const done=progress.completed.filter(id=>lessons(n).some(l=>l.id===id)).length;return `<div style="margin:20px 0"><div class="section-heading" style="margin-bottom:0"><h3 style="margin:0">HSK${n} · ${levelNames[n]}</h3><a class="text-link" href="${href('lessons',n)}">${done}/${lessons(n).length} bài →</a></div><div class="progress-track"><i style="width:${done/lessons(n).length*100}%"></i></div></div>`;}).join('')}</div><div class="panel"><div class="section-heading"><h2>Lịch sử gần đây</h2><span class="subtle">${progress.visits.length} ngày ghé học</span></div>${all.length?`<div class="table-shell"><table><thead><tr><th>THỜI ĐIỂM</th><th>CẤP ĐỘ</th><th>BÀI LÀM</th><th>KẾT QUẢ</th></tr></thead><tbody>${[...all].reverse().slice(0,20).map(a=>`<tr><td>${E(new Date(a.at).toLocaleString('vi-VN'))}</td><td>HSK${a.level}</td><td>${a.mode==='exam'?'Thi thử':'Luyện tập'}</td><td>${a.correct}/${a.total} · ${Math.round(a.correct/a.total*100)}%</td></tr>`).join('')}</tbody></table></div>`:'<p>Chưa có bài làm. Bắt đầu một bài luyện ngắn để ghi lại bước tiến đầu tiên.</p>'}<div class="actions-inline" style="margin-top:22px">${button('↓ Xuất bản sao tiến độ','export-progress')}${button('Nhập tiến độ','import-progress','','ghost')}</div></div>`;}
 function renderSources(){return `<div class="page-title"><a class="back-link" href="${href('library')}">← Thư viện</a><h1>Nội dung rõ nguồn, học tập chủ động.</h1><p>HaloChina là thư viện tự học độc lập. Danh mục được tổ chức theo cấp HSK1–HSK6; bài học và bài luyện do HaloChina biên soạn.</p></div><article class="panel"><h2>Phạm vi nội dung</h2><p>5.400 mục từ mới thuộc các cấp 1–6, theo bản đề cương thi HSK công bố tháng 11/2025: 300 / 200 / 500 / 1.000 / 1.600 / 1.800 mục. Các số này là mục từ trong nguồn, có thể có từ đồng hình khác cách đọc. Đây là lý do số liệu khác một số website đã gộp hoặc loại trùng.</p><p>108 bài học ngắn và 108 điểm ngữ pháp có ví dụ, pinyin, bản dịch tiếng Việt, lưu ý và bài tập. Phân cấp bài học là lộ trình biên soạn của HaloChina, không tuyên bố sao chép một giáo trình hoặc toàn bộ đề cương ngữ pháp chính thức. Sáu chuyên đề kỹ năng có thể áp dụng ở mọi cấp.</p><h2>Nguồn dữ liệu & giấy phép</h2><ul class="license-list"><li><a href="https://github.com/uranbekanarbaev/hsk-3.0-vocabulary-dataset" target="_blank" rel="noopener noreferrer">HSK 3.0 vocabulary dataset · hsk-tutor.com</a>: đối chiếu chữ Hán, pinyin, cấp độ và số trang của đề cương 2025-11. Quyền đối với đề cương nguồn thuộc đơn vị phát hành; HaloChina không phân phối lại đề thi hay bản PDF gốc. <a href="https://www.chinesetest.cn/HSK" target="_blank" rel="noopener noreferrer">Thông tin kỳ thi chính thức</a>.</li><li><a href="https://github.com/ph0ngp/CVDICT" target="_blank" rel="noopener noreferrer">CVDICT · Phong Phan</a>: nghĩa tiếng Việt, phái sinh từ CC-CEDICT; giấy phép <a href="https://creativecommons.org/licenses/by-sa/4.0/" target="_blank" rel="noopener noreferrer">CC BY-SA 4.0</a>. Nguồn có sử dụng dịch hỗ trợ bằng AI và có thể còn lỗi. HaloChina lọc theo cấp độ, ghép với pinyin, bổ sung một số giải nghĩa cơ bản.</li><li><a href="https://github.com/drkameleon/complete-hsk-vocabulary" target="_blank" rel="noopener noreferrer">Complete HSK Vocabulary · Yanis Zafirópulos</a>: từ điển hỗ trợ đối chiếu dạng chữ, pinyin, nghĩa tiếng Anh. Mã nguồn công cụ theo MIT; nghĩa gốc từ <a href="https://www.mdbg.net/chinese/dictionary?page=cedict" target="_blank" rel="noopener noreferrer">CC-CEDICT</a> theo CC BY-SA 4.0. <a href="data/DICTIONARY-LICENSE.txt" target="_blank" rel="noopener noreferrer">Thông báo MIT</a>.</li><li><a href="https://github.com/ph0ngp/hanviet-pinyin-wordlist" target="_blank" rel="noopener noreferrer">hanviet-pinyin-wordlist · Phong Phan</a>: âm Hán Việt theo pinyin, ưu tiên đối chiếu chữ phồn thể và cách đọc; giấy phép MIT. <a href="data/HANVIET-LICENSE.txt" target="_blank" rel="noopener noreferrer">Thông báo MIT</a>.</li><li><a href="https://www.unicode.org/charts/unihan.html" target="_blank" rel="noopener noreferrer">Unicode Unihan · Unicode, Inc.</a>: trường kVietnamese bổ sung cách đọc theo từng chữ khi bảng âm Hán Việt chưa có, không phải cách đọc tiếng Trung hay phân tích từ ghép. <a href="data/UNICODE-LICENSE.txt" target="_blank" rel="noopener noreferrer">Unicode License V3</a>.</li></ul><p>Bộ từ điển đã lọc và bổ sung được cung cấp tại <a class="text-link" href="data/vocabulary.js" download>vocabulary.js</a> theo CC BY-SA 4.0; khi sử dụng lại cần giữ ghi nguồn và chia sẻ phần dữ liệu phái sinh theo cùng giấy phép. <a class="text-link" href="data/ATTRIBUTION.txt" download>Tải thông tin ghi nguồn</a>.</p><h2>Cách hoạt động</h2><p>Từ đã lưu, từ đã nhớ, bản nháp và điểm luyện tập nằm trong localStorage của trình duyệt. HaloChina không có tài khoản, đồng bộ máy chủ hoặc thu thập thông tin cá nhân. Xóa dữ liệu trình duyệt có thể xóa tiến độ; dùng chức năng xuất JSON để sao lưu.</p><p>Âm thanh dùng Web Speech API và giọng tiếng Trung có trên thiết bị. Có thể không phát được hoặc cần mạng tùy hệ điều hành. Bài nghe tổng hợp không thay thế hoàn toàn bản ghi âm người thật. Tài liệu PDF được tạo qua hộp thoại in của trình duyệt.</p><p>Trang này không liên kết với 123tiengtrung.com và không phân phối lại kho tài liệu của website đó. Giao diện dùng cấu trúc thư viện theo cấp mà bạn yêu cầu.</p></article>`;}
 function renderNotFound(){return `<div class="empty"><h2>Trang này chưa tồn tại</h2><p>Quay lại thư viện để chọn một tài liệu.</p><a class="button" href="#/library/1">Về thư viện</a></div>`;}
 function parseRoute(){const parts=location.hash.replace(/^#\/?/,'').split('/');const view=parts[0]||'library';return {view,level:Math.min(6,Math.max(1,parseInt(parts[1],10)||1)),id:parts[2]||''};}
 function render(){route=parseRoute();renderNav();const screens={library:renderLibrary,vocabulary:()=>renderVocabulary(false),saved:()=>renderVocabulary(true),grammar:renderGrammar,lessons:renderLessons,lesson:renderLesson,topics:renderTopics,guide:renderGuide,roadmap:renderRoadmap,downloads:renderDownloads,practice:()=>renderSetup('practice'),exam:()=>renderSetup('exam'),quiz:renderQuiz,results:renderResults,progress:renderProgress,sources:renderSources,games:()=>window.HaloGame.renderMap(route),game:()=>window.HaloGame.renderPlay(route),'game-result':()=>window.HaloGame.renderResult(route),'game-guide':()=>window.HaloGame.renderGuide(route),communication:()=>window.HaloDaily.renderHome(route),'daily-topic':()=>window.HaloDaily.renderTopic(route)};$('#main').innerHTML=(screens[route.view]||renderNotFound)();$('#main').dataset.view=route.view;window.HaloGame.afterRender(route);window.HaloDaily.afterRender(route);window.HaloFocus.afterRender();syncSaveStatus();document.title=`${route.view==='library'?'Nga Anh học tiếng Trung':$('#main h1')?.textContent||'Học tiếng Trung'} · HaloChina`;tickTimer();}
 function speak(text,options={}){
  if(!('speechSynthesis' in window)){toast('Trình duyệt chưa hỗ trợ phát âm. Hãy thử Chrome hoặc Edge.');options.onError?.('unsupported');return false;}
  const synth=window.speechSynthesis,voices=synth.getVoices(),voice=voices.find(v=>/^zh[-_]CN$/i.test(v.lang))||voices.find(v=>/^zh/i.test(v.lang));
  if(!voice&&voices.length){toast('Thiết bị chưa có giọng tiếng Trung. Hãy thêm giọng zh-CN trong cài đặt hệ điều hành.');options.onError?.('no-voice');return false;}
  synth.cancel();const u=new SpeechSynthesisUtterance(text);u.lang='zh-CN';u.rate=Number.isFinite(options.rate)?Math.max(.5,Math.min(1.2,options.rate)):.8;if(voice)u.voice=voice;
  const restoreMusic=window.HaloMusic?.beginSpeech()||(()=>{});u.onend=()=>{restoreMusic();options.onEnd?.();};
  u.onerror=e=>{restoreMusic();options.onError?.(e.error);if(e.error!=='interrupted'&&e.error!=='canceled')toast('Chưa phát được âm thanh. Kiểm tra giọng tiếng Trung và kết nối của thiết bị.');};
  try{synth.speak(u);return u;}catch{restoreMusic();options.onError?.('failed');toast('Chưa phát được âm thanh trên thiết bị này.');return false;}
 }
 function openDialog(title,body){$('#dialog-content').innerHTML=`<div class="dialog-head"><h2 id="dialog-title">${E(title)}</h2><button class="icon-button" data-action="close-dialog" aria-label="Đóng">${icon('close')}</button></div><div class="dialog-body">${body}</div>`;if(!$('#reader-dialog').open)$('#reader-dialog').showModal();}
 function flashOpen(){const words=C.shuffle(currentWords(route.view==='saved'));if(!words.length){toast('Không có từ nào trong bộ lọc hiện tại.');return;}flash={words,index:0,flipped:false};renderFlash();}
 function renderFlash(){const w=flash.words[flash.index];openDialog('Ôn từ bằng flashcard',`<div class="flash-progress">HSK${w.level} · Thẻ ${flash.index+1} / ${flash.words.length} · ${progress.known.includes(w.id)?'✓ Đã nhớ':'Chưa đánh dấu nhớ'}</div><button class="flashcard" data-action="flash-flip" aria-label="${flash.flipped?'Hiện mặt chữ':'Lật thẻ xem nghĩa'}">${flash.flipped?`<span class="flash-meaning">${E(w.vi||w.en)}</span><span class="hanviet">Hán Việt: ${E(w.hanviet)}</span>`:`<span class="flash-hanzi" lang="zh">${E(w.hanzi)}</span><span class="pinyin">${E(w.pinyin)}</span>`}<span class="flash-hint">Bấm để lật thẻ</span></button><div class="flash-actions">${button('←','flash-prev',flash.index===0?'disabled':'','ghost')}${button(icon('sound'),'flash-speak','aria-label="Nghe từ"','ghost')}${button(progress.known.includes(w.id)?'✓ Đã nhớ':'Đã nhớ','flash-known')}${button('Chưa nhớ','flash-unknown','','ghost')}${button('→','flash-next',flash.index===flash.words.length-1?'disabled':'','ghost')}</div>`);}
 function download(filename,text,type='text/plain;charset=utf-8'){const blob=new Blob([text],{type}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=filename;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
 const attribution='Nguồn: CVDICT (Phong Phan) / CC-CEDICT, CC BY-SA 4.0; đối chiếu đề cương HSK 2025-11; âm Hán Việt: Phong Phan (MIT), Unicode Unihan. HaloChina lọc, ghép và bổ sung dữ liệu. https://github.com/ph0ngp/CVDICT · https://creativecommons.org/licenses/by-sa/4.0/';
 function exportVocab(all=false,selftest=false){const a=all?vocab(route.level):currentWords(route.view==='saved');if(!a.length){toast('Không có từ để xuất.');return;}const rows=[selftest?['Chữ Hán','Pinyin','Nghĩa tự điền','Đáp án tham khảo','Cấp độ','Ghi nguồn']:['Chữ Hán','Pinyin','Âm Hán Việt theo chữ','Nghĩa tiếng Việt','Cấp độ','Ghi nguồn'],...a.map(w=>selftest?[w.hanzi,w.pinyin,'',w.vi||w.en,`HSK${w.level}`,attribution]:[w.hanzi,w.pinyin,w.hanviet,w.vi||w.en,`HSK${w.level}`,attribution])];download(`HaloChina-HSK${route.level}-${selftest?'tu-kiem-tra':'tu-vung'}.csv`,C.csv(rows),'text/csv;charset=utf-8');toast(`Đã xuất ${a.length} mục từ.`);}
 function printDocument(title,body){const p=window.open('','_blank');if(!p){toast('Trình duyệt chặn cửa sổ in. Hãy cho phép cửa sổ bật lên cho HaloChina.');return;}p.document.write(`<!doctype html><html lang="vi"><head><meta charset="utf-8"><title>${E(title)} · HaloChina</title><style>body{font-family:'Segoe UI',Arial,sans-serif;color:#233d3a;line-height:1.7;padding:25px;max-width:1000px;margin:auto}h1{font-size:24px}h2{font-size:18px;margin-top:25px}h3{font-size:15px}p{font-size:12px}table{width:100%;border-collapse:collapse;font-size:11px}td,th{padding:8px;border:1px solid #d9dfd0;text-align:left}th{background:#edf2e5}.zh{font-size:20px}.grammar{break-inside:avoid;border-bottom:1px solid #ddd;padding:15px 0}.py{color:#927649}.note{font-size:10px;color:#68745f}button{padding:10px 17px;background:#174c46;color:white;border:0;border-radius:6px;cursor:pointer}.writing-row{break-inside:avoid;margin-bottom:24px}.writing-label{font-size:14px;margin:8px 0}.cells{display:flex;flex-wrap:wrap}.cell{position:relative;width:52px;height:52px;border:1px solid #bdcbb0;margin-right:5px;margin-bottom:5px;font-size:35px;line-height:52px;text-align:center;color:#b0baa4;background:linear-gradient(0deg,transparent 49%,#e2e7dc 49%,#e2e7dc 51%,transparent 51%),linear-gradient(90deg,transparent 49%,#e2e7dc 49%,#e2e7dc 51%,transparent 51%)}@media print{body{padding:0}button,.instructions{display:none}thead{display:table-header-group}tr{break-inside:avoid}.answer-key{break-before:page}}</style></head><body><button id="print-trigger">In / lưu PDF</button><p class="instructions">Chọn “Lưu dưới dạng PDF” trong cửa sổ in để tải tài liệu. Nếu cần, bấm nút ở trên để mở lại cửa sổ in.</p><h1>${E(title)}</h1><p class="note">HaloChina · Nội dung học tập độc lập</p>${body}<hr><p class="note">${E(attribution)}. Bài học và lời giải: HaloChina. Âm Hán Việt theo từng chữ có thể có nhiều cách đọc.</p></body></html>`);p.document.close();p.document.getElementById('print-trigger').addEventListener('click',()=>p.print());p.focus();setTimeout(()=>p.print(),350);}
 function printVocab(all=false){const a=all?vocab(route.level):currentWords(route.view==='saved');if(!a.length){toast('Không có từ để in.');return;}printDocument(`Từ vựng HSK${route.level} · ${a.length} mục`, `<table><thead><tr><th>Chữ Hán</th><th>Pinyin</th><th>Hán Việt</th><th>Nghĩa tiếng Việt</th></tr></thead><tbody>${a.map(w=>`<tr><td class="zh">${E(w.hanzi)}</td><td>${E(w.pinyin)}</td><td>${E(w.hanviet)}</td><td>${E(w.vi||w.en)}</td></tr>`).join('')}</tbody></table>`);}
 function printGrammar(){const a=lessons(route.level);printDocument(`Sổ tay ngữ pháp HSK${route.level}`,a.map(l=>`<section class="grammar"><h2>${l.number}. ${E(l.grammar)}</h2><p><strong>${E(l.pattern)}</strong></p><p>${E(l.explanation)}</p><p class="zh">${E(l.zh)}</p><p class="py">${E(l.pinyin)}</p><p>${E(l.vi)}</p><p><strong>Lưu ý:</strong> ${E(l.tip)}</p></section>`).join(''));}
 function printHandwriting(){const saved=V.filter(w=>w.level===route.level&&progress.saved.includes(w.id)),a=saved.length?saved:vocab(route.level);printDocument(`Phiếu luyện viết HSK${route.level} · ${saved.length?'từ đã lưu':'toàn cấp'}`,`<p>${a.length} từ. Các ô để luyện bố cục chữ; phiếu không hướng dẫn hay tự kiểm tra thứ tự nét.</p>`+a.map(w=>`<section class="writing-row"><div class="writing-label">${E(w.hanzi)} · ${E(w.pinyin)} · ${E(C.gloss(w))}</div><div class="cells">${[...w.hanzi].map(c=>`<span class="cell">${E(c)}</span>${'<span class="cell"></span>'.repeat(3)}`).join('')}</div></section>`).join(''));}
 function printExercises(){const a=lessons(route.level);printDocument(`Bài tập ngữ pháp HSK${route.level}`,a.map(l=>`<section class="grammar"><h3>${l.number}. ${E(l.cloze)}</h3><p>${C.shuffle([l.answer,...l.wrong]).map((x,i)=>`${'ABCD'[i]}. ${E(x)}`).join('　')}</p></section>`).join('')+`<section class="answer-key"><h2>Đáp án & giải thích</h2>${a.map(l=>`<h3>${l.number}. ${E(l.answer)}</h3><p>${E(l.explanation)} ${E(l.tip)}</p>`).join('')}</section>`);}
 function importProgress(){openDialog('Nhập bản sao tiến độ',`<p class="subtle">Chọn tệp JSON được xuất từ HaloChina. Bản nhập sẽ thay thế tiến độ hiện tại trên trình duyệt này; hãy xuất bản sao trước nếu bạn cần giữ dữ liệu cũ.</p><label for="progress-file">Tệp tiến độ HaloChina</label><input id="progress-file" type="file" accept="application/json,.json" style="display:block;margin-top:12px;width:100%"><div id="import-message" role="status" class="subtle" style="margin:14px 0"></div><div class="actions-inline">${button('Nhập và thay thế tiến độ','confirm-import')}${button('Đóng','close-dialog','','ghost')}</div>`);}
 document.addEventListener('click',async e=>{const el=e.target.closest('[data-action]');if(!el)return;const a=el.dataset.action,id=el.dataset.id;switch(a){
  case 'speak-word':speak(V.find(w=>w.id===Number(id))?.hanzi||'');break;
  case 'speak-lesson':speak(L.find(l=>l.id===id)?.zh||'');break;
  case 'save-word':case 'know-word':{const key=a==='save-word'?'saved':'known',n=Number(id),i=progress[key].indexOf(n);if(i>=0)progress[key].splice(i,1);else progress[key].push(n);persist();$('#vocab-results').innerHTML=vocabResults(route.view==='saved');renderNav();break;}
  case 'vocab-prev':changeVocabPage(listPage-1);break;
  case 'vocab-next':changeVocabPage(listPage+1);break;
  case 'vocab-page':changeVocabPage(Number(el.dataset.page));break;
  case 'flash-open':flashOpen();break;
  case 'flash-flip':flash.flipped=!flash.flipped;renderFlash();break;
  case 'flash-prev':flash.index=Math.max(0,flash.index-1);flash.flipped=false;renderFlash();break;
  case 'flash-next':flash.index=Math.min(flash.words.length-1,flash.index+1);flash.flipped=false;renderFlash();break;
  case 'flash-speak':speak(flash.words[flash.index].hanzi);break;
  case 'flash-known':case 'flash-unknown':{const wordId=flash.words[flash.index].id;progress.known=progress.known.filter(n=>n!==wordId);if(a==='flash-known')progress.known.push(wordId);persist();if(flash.index<flash.words.length-1){flash.index++;flash.flipped=false;}else toast('Bạn đã xem đến thẻ cuối. Có thể quay lại để ôn tiếp.');renderFlash();break;}
  case 'close-dialog':$('#reader-dialog').close();if(route.view==='vocabulary'||route.view==='saved')$('#vocab-results').innerHTML=vocabResults(route.view==='saved');break;
  case 'complete-lesson':if(!progress.completed.includes(id)){progress.completed.push(id);persist();el.textContent='✓ Đã hoàn thành';toast('Đã lưu bài học hoàn thành.');}break;
  case 'inline-answer':{const l=L.find(x=>x.id===id),correct=el.dataset.answer===l.answer;$('#inline-exercise').querySelectorAll('button').forEach(b=>{b.disabled=true;if(b.dataset.answer===l.answer)b.classList.add('correct');});if(!correct)el.classList.add('incorrect');$('#inline-feedback').innerHTML=`<div class="feedback ${correct?'':'wrong'}">${correct?'✓ Chính xác.':'Cùng xem lại nhé.'} Đáp án: ${E(l.answer)}. ${E(l.explanation)}</div>`;break;}
  case 'start-quiz':startQuiz(el.dataset.mode);break;
  case 'resume-quiz':activeSession=loadSession();if(activeSession){location.hash=`#/quiz/${activeSession.level}`;if(route.view==='quiz')render();}break;
  case 'discard-quiz':openDialog('Bỏ bài đang làm?',`<p class="subtle">Các câu trả lời của bài đang dở sẽ bị xóa. Tiến độ từ vựng và các bài đã nộp vẫn được giữ.</p><div class="actions-inline">${button('Bỏ bài đang dở','confirm-discard','','danger')}${button('Giữ lại','close-dialog','','ghost')}</div>`);break;
  case 'confirm-discard':activeSession=null;saveSession();$('#reader-dialog').close();render();break;
  case 'quiz-answer':if(activeSession){const q=activeSession.questions[activeSession.index];if(activeSession.mode==='practice'&&activeSession.answers[q.id]!==undefined)break;activeSession.answers[q.id]=el.dataset.answer;saveSession();render();}break;
  case 'quiz-prev':activeSession.index=Math.max(0,activeSession.index-1);saveSession();render();break;
  case 'quiz-next':activeSession.index=Math.min(activeSession.questions.length-1,activeSession.index+1);saveSession();render();break;
  case 'quiz-goto':activeSession.index=Number(el.dataset.index);saveSession();render();break;
  case 'speak-question':speak(activeSession.questions[activeSession.index].speak);break;
  case 'submit-quiz':requestSubmit();break;
  case 'confirm-submit':finishQuiz();break;
  case 'retry-wrong':{if(loadSession()){toast('Bạn đang có bài chưa hoàn thành. Hãy làm tiếp hoặc bỏ bài đó trước.');break;}const s=getResult(),wrong=s.questions.filter(q=>s.answers[q.id]!==q.answer);if(!wrong.length){toast('Bạn đã trả lời đúng tất cả câu. Hãy bắt đầu bài luyện mới.');break;}activeSession={mode:'practice',level:s.level,questions:C.shuffle(wrong),answers:{},index:0,startedAt:Date.now(),duration:0};saveSession();location.hash=`#/quiz/${s.level}`;break;}
  case 'test-sound':speak('你好，欢迎学习汉语。');break;
  case 'export-vocab':exportVocab();break;
  case 'export-all-vocab':exportVocab(true);break;
  case 'export-selftest':exportVocab(true,true);break;
  case 'print-vocab':printVocab();break;
  case 'print-all-vocab':printVocab(true);break;
  case 'print-grammar':printGrammar();break;
  case 'print-handwriting':printHandwriting();break;
  case 'print-exercises':printExercises();break;
  case 'print-page':window.print();break;
  case 'export-progress':download(`HaloChina-tien-do-${today()}.json`,JSON.stringify(progress,null,2),'application/json');break;
  case 'import-progress':importProgress();break;
  case 'confirm-import':{const file=$('#progress-file').files[0];if(!file){$('#import-message').textContent='Hãy chọn một tệp JSON trước.';break;}if(file.size>2e6){$('#import-message').textContent='Tệp vượt quá giới hạn 2 MB.';break;}try{const imported=C.validProgress(JSON.parse(await file.text()));progress=imported;persist();$('#reader-dialog').close();render();toast('Đã nhập tiến độ học tập.');}catch(error){$('#import-message').textContent=error.message||'Không đọc được tệp.';}break;}
  case 'export-result':{const s=getResult();download(`HaloChina-ket-qua-HSK${s.level}.csv`,C.csv([['Câu','Loại','Câu hỏi','Bạn chọn','Đáp án','Giải thích'],...s.questions.map((q,i)=>[i+1,q.label,q.prompt,s.answers[q.id]||'',q.answer,q.explanation])]),'text/csv;charset=utf-8');break;}
 }});
 document.addEventListener('input',e=>{if(e.target.id==='vocab-search'){query=e.target.value;listPage=1;$('#vocab-results').innerHTML=vocabResults(route.view==='saved');}if(e.target.id==='grammar-search'){grammarQuery=e.target.value;$('#grammar-results').innerHTML=grammarResults();}if(e.target.id==='lesson-draft'){progress.drafts[e.target.dataset.id]=e.target.value.slice(0,20000);persist();}});
 document.addEventListener('change',e=>{if(e.target.matches('[data-vocab-page]')){changeVocabPage(e.target.value);return;}if(e.target.id==='include-previous'){includePrevious=e.target.checked;listPage=1;$('#vocab-results').innerHTML=vocabResults();}if(e.target.id==='only-unknown'){onlyUnknown=e.target.checked;listPage=1;$('#vocab-results').innerHTML=vocabResults(route.view==='saved');}});
 $('#menu-toggle').addEventListener('click',()=>{const open=$('#sidebar').classList.toggle('open');$('#menu-toggle').setAttribute('aria-expanded',String(open));});
 document.addEventListener('click',e=>{if($('#sidebar').classList.contains('open')&&!e.target.closest('#sidebar')&&!e.target.closest('#menu-toggle')){$('#sidebar').classList.remove('open');$('#menu-toggle').setAttribute('aria-expanded','false');}});
 $('#reader-dialog').addEventListener('click',e=>{if(e.target===$('#reader-dialog'))$('#reader-dialog').close();});
 window.addEventListener('hashchange',()=>{query='';grammarQuery='';listPage=1;$('#sidebar').classList.remove('open');$('#menu-toggle').setAttribute('aria-expanded','false');if('speechSynthesis'in window)window.speechSynthesis.cancel();render();window.scrollTo(0,0);$('#main').focus({preventScroll:true});});
 window.addEventListener('pagehide',()=>{if(activeSession)saveSession();});
 window.HaloGame.init({C,V,L,G,get progress(){return progress;},persist,toast,speak,icon,button,openDialog,render});
 window.HaloDaily.init({C,get progress(){return progress;},persist,toast,speak,icon,download,render});
 window.HaloFocus.init({getActivity:()=>route.view==='quiz'&&activeSession?{key:`quiz:${activeSession.startedAt}:${activeSession.mode}`,kind:'quiz'}:window.HaloGame.getActivity()});
 if(!location.hash)history.replaceState(null,'','#/library/1');render();if(!storageOK)toast('Tiến độ hiện chưa lưu được. Bạn vẫn có thể học và xuất bản sao.');
})();
